-- Durable, owner-accountable redaction pages. Executable run state stays local;
-- the existing product audit keeps each run's actor and outcome in archives.
CREATE TABLE penny_redaction_content(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL DEFAULT 0);
INSERT INTO penny_redaction_content(singleton,revision) VALUES(1,0);
CREATE TABLE penny_redaction_runs(
 id TEXT PRIMARY KEY NOT NULL,operator_id TEXT NOT NULL,operator_version INTEGER NOT NULL,actor_id TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('previewing','ready','running','complete','failed')),
 resume_state TEXT NOT NULL CHECK(resume_state IN ('previewing','running')),
 rules_revision INTEGER NOT NULL,content_revision INTEGER NOT NULL,
 place_index INTEGER NOT NULL DEFAULT 0,after_row INTEGER NOT NULL DEFAULT 0,
 bounds_json TEXT NOT NULL CHECK(json_valid(bounds_json)),counts_json TEXT NOT NULL CHECK(json_valid(counts_json)),
 records INTEGER NOT NULL DEFAULT 0,changes INTEGER NOT NULL DEFAULT 0,changed INTEGER NOT NULL DEFAULT 0,scanned INTEGER NOT NULL DEFAULT 0,
 step INTEGER NOT NULL DEFAULT 0,plan_hash TEXT,error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL
);
CREATE INDEX penny_redaction_due ON penny_redaction_runs(state);
